-- ---------- 20261025000100_cms_schema.sql ----------
begin;

-- ---------------------------------------------------------------------------
-- 1. Tables & Constraints
-- ---------------------------------------------------------------------------

create table if not exists public.posts (
  id bigint generated by default as identity primary key,
  title text not null,
  slug text not null,
  content text not null default '',
  status text not null default 'draft',
  subtitle text not null default '',
  summary text not null default '',
  category text not null default 'Research Reviews',
  format text not null default 'Paper Review',
  author_id text,
  author_name text not null default 'ResearchWithMe editors',
  cover_image text,
  tags text[] not null default '{}',
  key_takeaways text[] not null default '{}',
  read_time text not null default '6 min read',
  featured boolean not null default false,
  likes integer not null default 0,
  published_at timestamptz,
  inserted_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),

  constraint posts_title_length check (char_length(title) between 1 and 180),
  constraint posts_slug_format check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and char_length(slug) between 1 and 96),
  constraint posts_slug_unique unique (slug),
  constraint posts_content_length check (char_length(content) <= 200000),
  constraint posts_summary_length check (char_length(summary) <= 1200),
  constraint posts_subtitle_length check (char_length(subtitle) <= 400),
  constraint posts_author_name_length check (char_length(author_name) between 1 and 120),
  constraint posts_tags_length check (cardinality(tags) <= 8),
  constraint posts_takeaways_length check (cardinality(key_takeaways) <= 8),
  constraint posts_likes_non_negative check (likes >= 0),
  constraint posts_status_allowed check (status in ('draft', 'published')),
  constraint posts_publish_ready check (
    status <> 'published'
    or (
      char_length(title) >= 8
      and char_length(content) >= 200
      and char_length(summary) >= 40
    )
  )
);

create table if not exists public.comments (
  id bigint generated by default as identity primary key,
  post_id bigint not null references public.posts (id) on delete cascade,
  author_name text not null default 'Reader',
  author_role text not null default 'Reader',
  content text not null,
  inserted_at timestamptz not null default timezone('utc', now()),

  constraint comments_author_name_length check (char_length(author_name) between 1 and 120),
  constraint comments_author_role_length check (char_length(author_role) <= 80),
  constraint comments_content_length check (char_length(content) between 2 and 4000)
);

-- ---------------------------------------------------------------------------
-- 2. Indexes
-- ---------------------------------------------------------------------------

create index if not exists posts_status_published_at_idx
  on public.posts (status, published_at desc nulls last);
create index if not exists posts_published_slug_idx
  on public.posts (slug) where status = 'published';
create index if not exists posts_author_id_idx on public.posts (author_id);
create index if not exists posts_inserted_at_idx on public.posts (inserted_at desc);

create index if not exists comments_post_id_inserted_at_idx
  on public.comments (post_id, inserted_at);
create index if not exists comments_inserted_at_idx on public.comments (inserted_at desc);

-- ---------------------------------------------------------------------------
-- 3. Triggers & Timestamp Management
-- ---------------------------------------------------------------------------

create or replace function public.touch_updated_at()
returns trigger
language plpgsql
security invoker
set search_path = 'public'
as $$
begin
  new.updated_at = timezone('utc', now());
  return new;
end;
$$;

create or replace function public.stamp_published_at()
returns trigger
language plpgsql
security invoker
set search_path = 'public'
as $$
begin
  if new.status = 'published' and new.published_at is null then
    new.published_at = timezone('utc', now());
  elsif new.status = 'draft' then
    new.published_at = null;
  end if;
  return new;
end;
$$;

drop trigger if exists posts_touch_updated_at on public.posts;
create trigger posts_touch_updated_at
  before insert or update on public.posts
  for each row execute function public.touch_updated_at();

drop trigger if exists posts_stamp_published_at on public.posts;
create trigger posts_stamp_published_at
  before insert or update on public.posts
  for each row execute function public.stamp_published_at();

-- ---------------------------------------------------------------------------
-- 4. Row Level Security (RLS)
-- ---------------------------------------------------------------------------

alter table public.posts enable row level security;
alter table public.comments enable row level security;

drop policy if exists "Published posts are publicly readable" on public.posts;
create policy "Published posts are publicly readable"
  on public.posts for select
  to anon, authenticated
  using (status = 'published');

drop policy if exists "Editors can read every post" on public.posts;
create policy "Editors can read every post"
  on public.posts for select
  to authenticated
  using (true);

drop policy if exists "Editors can create posts" on public.posts;
create policy "Editors can create posts"
  on public.posts for insert
  to authenticated
  with check (true);

drop policy if exists "Editors can update posts" on public.posts;
create policy "Editors can update posts"
  on public.posts for update
  to authenticated
  using (true)
  with check (true);

drop policy if exists "Editors can delete posts" on public.posts;
create policy "Editors can delete posts"
  on public.posts for delete
  to authenticated
  using (true);

drop policy if exists "Published comments are publicly readable" on public.comments;
create policy "Published comments are publicly readable"
  on public.comments for select
  to anon
  using (
    exists (
      select 1 from public.posts p
      where p.id = comments.post_id and p.status = 'published'
    )
  );

drop policy if exists "Editors can read all comments" on public.comments;
create policy "Editors can read all comments"
  on public.comments for select
  to authenticated
  using (true);

drop policy if exists "Anyone can post a comment" on public.comments;
create policy "Anyone can post a comment"
  on public.comments for insert
  to anon, authenticated
  with check (
    char_length(content) between 2 and 4000
    and char_length(author_name) between 1 and 120
    and char_length(author_role) <= 80
    and exists (
      select 1 from public.posts p
      where p.id = comments.post_id and p.status = 'published'
    )
  );

drop policy if exists "Editors can delete comments" on public.comments;
create policy "Editors can delete comments"
  on public.comments for delete
  to authenticated
  using (true);

-- ---------------------------------------------------------------------------
-- 5. RPC Functions
-- ---------------------------------------------------------------------------

create or replace function public.increment_post_likes(target_id bigint)
returns integer
language sql
security definer
set search_path = 'public'
as $$
  update public.posts
  set likes = likes + 1
  where id = target_id and status = 'published'
  returning likes;
$$;

revoke all on function public.increment_post_likes(bigint) from public;
grant execute on function public.increment_post_likes(bigint) to anon, authenticated;

-- ---------------------------------------------------------------------------
-- 6. Role Privileges
-- ---------------------------------------------------------------------------

grant usage on schema public to anon, authenticated;
grant select on public.posts to anon, authenticated;
grant insert, update, delete on public.posts to authenticated;
grant select, insert on public.comments to anon, authenticated;
grant delete on public.comments to authenticated;
grant usage, select on all sequences in schema public to anon, authenticated;

-- ---------------------------------------------------------------------------
-- 7. Realtime Replication
-- ---------------------------------------------------------------------------

do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    if not exists (
      select 1 from pg_publication_tables
      where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'posts'
    ) then
      execute 'alter publication supabase_realtime add table public.posts';
    end if;

    if not exists (
      select 1 from pg_publication_tables
      where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'comments'
    ) then
      execute 'alter publication supabase_realtime add table public.comments';
    end if;
  end if;
end;
$$;

commit;

-- ---------- 20261025000200_cms_storage.sql ----------
-- Step 1.3 of the Supabase blueprint: the public `blog-images` bucket.
--
-- Uploads are restricted to authenticated editors. Reads are public because the
-- rendered article needs to display the image without a signed URL. File type and
-- size limits are enforced by the bucket, not only by the browser.

begin;

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'blog-images',
  'blog-images',
  true,
  5242880,
  array['image/jpeg', 'image/png', 'image/webp', 'image/avif', 'image/gif']
)
on conflict (id) do update
  set public = excluded.public,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists "Blog images are publicly readable" on storage.objects;
create policy "Blog images are publicly readable"
  on storage.objects for select
  to anon, authenticated
  using (bucket_id = 'blog-images');

drop policy if exists "Editors can upload blog images" on storage.objects;
create policy "Editors can upload blog images"
  on storage.objects for insert
  to authenticated
  with check (bucket_id = 'blog-images');

drop policy if exists "Editors can replace blog images" on storage.objects;
create policy "Editors can replace blog images"
  on storage.objects for update
  to authenticated
  using (bucket_id = 'blog-images')
  with check (bucket_id = 'blog-images');

drop policy if exists "Editors can delete blog images" on storage.objects;
create policy "Editors can delete blog images"
  on storage.objects for delete
  to authenticated
  using (bucket_id = 'blog-images');

commit;

-- ---------- 20261025000300_cms_storage.sql ----------
begin;

create table if not exists public.editor_memberships (
  user_id uuid primary key references auth.users (id) on delete cascade,
  inserted_at timestamptz not null default now()
);

alter table public.editor_memberships enable row level security;
revoke all on public.editor_memberships from public, anon, authenticated;
grant select on public.editor_memberships to authenticated;
grant all on public.editor_memberships to service_role;

drop policy if exists "Editors can read their own membership" on public.editor_memberships;
create policy "Editors can read their own membership"
  on public.editor_memberships for select
  to authenticated
  using ((select auth.uid()) = user_id);

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'blog-images',
  'blog-images',
  true,
  5242880,
  array['image/jpeg', 'image/png', 'image/webp', 'image/avif', 'image/gif']
)
on conflict (id) do update
  set public = excluded.public,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

-- Public buckets serve objects by URL; avoid a SELECT policy that can expose listings.
drop policy if exists "Blog images are publicly readable" on storage.objects;

drop policy if exists "Editors can upload blog images" on storage.objects;
create policy "Editors can upload blog images"
  on storage.objects for insert
  to authenticated
  with check (
    bucket_id = 'blog-images'
    and exists (
      select 1 from public.editor_memberships em
      where em.user_id = (select auth.uid())
    )
  );

drop policy if exists "Editors can replace blog images" on storage.objects;
create policy "Editors can replace blog images"
  on storage.objects for update
  to authenticated
  using (
    bucket_id = 'blog-images'
    and exists (
      select 1 from public.editor_memberships em
      where em.user_id = (select auth.uid())
    )
  )
  with check (
    bucket_id = 'blog-images'
    and exists (
      select 1 from public.editor_memberships em
      where em.user_id = (select auth.uid())
    )
  );

drop policy if exists "Editors can delete blog images" on storage.objects;
create policy "Editors can delete blog images"
  on storage.objects for delete
  to authenticated
  using (
    bucket_id = 'blog-images'
    and exists (
      select 1 from public.editor_memberships em
      where em.user_id = (select auth.uid())
    )
  );

commit;

-- ---------- 20261028000100_editor_allowlist.sql ----------
-- Editor allowlist for the editorial studio.
--
-- Until now every `authenticated` user was treated as an editor. That held
-- while administrators created every account by hand, but with Google, GitHub,
-- and email sign-in enabled anyone can create an account. Writes to posts,
-- comment moderation, and image uploads now require a row in public.editors.
--
-- Signing in still works for everyone; it simply grants no studio access.
--
-- Grant access (SQL editor, run as the project owner):
--   insert into public.editors (user_id, note)
--   select id, 'founding editor' from auth.users where email = 'you@example.org'
--   on conflict (user_id) do nothing;
--
-- Revoke access:
--   delete from public.editors where user_id = '<uuid>';
--
-- Idempotent: safe to re-run.

begin;

create table if not exists public.editors (
  user_id uuid primary key references auth.users (id) on delete cascade,
  note text check (note is null or char_length(note) <= 200),
  added_at timestamptz not null default now()
);

alter table public.editors enable row level security;

-- A signed-in user may see their own row (and nothing else). There are no
-- insert, update, or delete policies: membership is managed with SQL or the
-- service role only, never from the browser.
drop policy if exists "Users can see their own editor row" on public.editors;
create policy "Users can see their own editor row"
  on public.editors for select
  to authenticated
  using (user_id = auth.uid());

revoke all on public.editors from anon, authenticated;
grant select on public.editors to authenticated;

-- SECURITY DEFINER so policies on other tables can consult the allowlist
-- without granting broader read access to it.
create or replace function public.is_editor()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.editors e where e.user_id = (select auth.uid())
  );
$$;

revoke all on function public.is_editor() from public;
grant execute on function public.is_editor() to anon, authenticated;

-- ---------------------------------------------------------------------------
-- Posts
-- ---------------------------------------------------------------------------
drop policy if exists "Editors can read every post" on public.posts;
create policy "Editors can read every post"
  on public.posts for select
  to authenticated
  using ((select public.is_editor()));

drop policy if exists "Editors can create posts" on public.posts;
create policy "Editors can create posts"
  on public.posts for insert
  to authenticated
  with check ((select public.is_editor()));

drop policy if exists "Editors can update posts" on public.posts;
create policy "Editors can update posts"
  on public.posts for update
  to authenticated
  using ((select public.is_editor()))
  with check ((select public.is_editor()));

drop policy if exists "Editors can delete posts" on public.posts;
create policy "Editors can delete posts"
  on public.posts for delete
  to authenticated
  using ((select public.is_editor()));

-- ---------------------------------------------------------------------------
-- Comments
-- ---------------------------------------------------------------------------
-- Signed-in non-editors are readers: they see the same published discussion
-- as anonymous visitors. The original policy only covered `anon`.
drop policy if exists "Published comments are publicly readable" on public.comments;
create policy "Published comments are publicly readable"
  on public.comments for select
  to anon, authenticated
  using (
    exists (
      select 1 from public.posts p
      where p.id = post_id and p.status = 'published'
    )
  );

drop policy if exists "Editors can read all comments" on public.comments;
create policy "Editors can read all comments"
  on public.comments for select
  to authenticated
  using ((select public.is_editor()));

drop policy if exists "Editors can delete comments" on public.comments;
create policy "Editors can delete comments"
  on public.comments for delete
  to authenticated
  using ((select public.is_editor()));

-- ---------------------------------------------------------------------------
-- Storage: blog-images bucket
-- ---------------------------------------------------------------------------
drop policy if exists "Editors can upload blog images" on storage.objects;
create policy "Editors can upload blog images"
  on storage.objects for insert
  to authenticated
  with check (bucket_id = 'blog-images' and (select public.is_editor()));

drop policy if exists "Editors can replace blog images" on storage.objects;
create policy "Editors can replace blog images"
  on storage.objects for update
  to authenticated
  using (bucket_id = 'blog-images' and (select public.is_editor()))
  with check (bucket_id = 'blog-images' and (select public.is_editor()));

drop policy if exists "Editors can delete blog images" on storage.objects;
create policy "Editors can delete blog images"
  on storage.objects for delete
  to authenticated
  using (bucket_id = 'blog-images' and (select public.is_editor()));

commit;
